# Plot the cumulative AED distribution generated by AED_cdf_generator.pl.

library(ggplot2)

WORKDIR <- "/data/users/srais/genome_annotation_course"

input <- file.path(
    WORKDIR,
    "output/MAKER/final/assembly.all.maker.renamed.gff.AED.txt"
)

outdir <- file.path(WORKDIR, "plots/MAKER_quality")
dir.create(outdir, recursive = TRUE, showWarnings = FALSE)

# Read the AED thresholds and cumulative proportions.
aed <- read.delim(
    input,
    header = TRUE,
    check.names = FALSE
)

stopifnot(ncol(aed) == 2)
names(aed) <- c("AED", "Proportion")

# Draw the cumulative distribution.
p <- ggplot(aed, aes(x = AED, y = Proportion)) +
    geom_line(colour = "#0055B8", linewidth = 1) +
    geom_vline(
        xintercept = 0.5,
        linetype = "dashed",
        colour = "grey40"
    ) +
    scale_x_continuous(
        limits = c(0, 1),
        breaks = seq(0, 1, 0.1)
    ) +
    scale_y_continuous(
        limits = c(0, 1),
        breaks = seq(0, 1, 0.1),
        labels = function(x) paste0(round(x * 100), "%")
    ) +
    labs(
        title = "MAKER cumulative AED distribution",
        x = "Annotation Edit Distance (AED)",
        y = "Cumulative proportion of models",
        caption = "Dashed line: AED = 0.5"
    ) +
    theme_classic(base_size = 12)

ggsave(
    filename = file.path(outdir, "01_MAKER_AED_cumulative.pdf"),
    plot = p,
    width = 8,
    height = 5
)